# owner: platform
"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _holes(merged: List[Span], opening: Span) -> List[Span]:
    holes = []
    cursor = opening.start
    for span in merged:
        if span.start > cursor:
            holes.append(Span(cursor, span.start))
        cursor = span.end
    if cursor < opening.end:
        holes.append(Span(cursor, opening.end))
    return holes


def _check_inside(merged: List[Span], opening: Span):
    for span in merged:
        if span.start < opening.start:
            raise ValueError(f"outside opening: {span}")
        if span.end > opening.end:
            raise ValueError(f"outside opening: {span}")


def _label(hole: Span) -> str:
    return f"gap {format_span(hole)} ({hole.minutes} min)"


# ---
def find_gaps(worked: Iterable[Span], opening: Span):
    """Label each uncovered stretch of opening hours."""
    merged = merge_spans(worked)
    _check_inside(merged, opening)
    holes = _holes(merged, opening)
    return [_label(hole) for hole in holes]
